'use client';

import { useState } from 'react';

import {
  ChevronsUpDownIcon,
  PlusIcon,
  SettingsIcon,
  UsersIcon,
} from '@/registry/ndeko/lib/icons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuGroupLabel,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

import { MorphLabel } from './_parts/morph-label';
import { SlidingCount } from './_parts/sliding-count';
import { Swap } from './_parts/swap';
import { TeamTile } from './_parts/team-tile';
import { TEAMS, memberCountLabelOf, type Team } from './_parts/teams';

const TRIGGER =
  'inline-flex h-8 max-w-full cursor-pointer items-center gap-2 rounded-full bg-card ps-1 pe-2.5 text-[13px] font-medium outline-none hairline-ring ring-foreground/12 shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-colors duration-150 hover:bg-foreground/[0.03] focus-visible:ring-[3px] focus-visible:ring-ring/25 data-popup-open:bg-foreground/[0.04] dark:bg-foreground/[0.04]';

function countOf(count: number) {
  return String(count);
}

function isTeamId(value: unknown): value is string {
  return TEAMS.some((team) => team.id === value);
}

function triggerLabelOf(team: Team) {
  const members = memberCountLabelOf(team.memberCount);
  return `Team: ${team.name}, ${members}. Switch team`;
}

function teamById(teamId: string) {
  const found = TEAMS.find((team) => team.id === teamId);
  if (found) {
    return found;
  }
  return TEAMS[0];
}

function TeamRow({ team }: { team: Team }) {
  return (
    <>
      <TeamTile name={team.name} color={team.color} />
      <span className='min-w-0 flex-1 truncate'>{team.name}</span>
      <span className='text-muted-foreground text-xs tabular-nums'>
        {team.memberCount}
        <span className='sr-only'> members</span>
      </span>
    </>
  );
}

export default function Teams02() {
  const [currentId, setCurrentId] = useState(TEAMS[0].id);
  const current = teamById(currentId);
  const triggerLabel = triggerLabelOf(current);

  function switchTeam(value: unknown) {
    if (isTeamId(value)) {
      setCurrentId(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger aria-label={triggerLabel} className={TRIGGER}>
        <Swap swapKey={current.id}>
          <TeamTile name={current.name} color={current.color} />
        </Swap>
        <MorphLabel value={current.id}>{current.name}</MorphLabel>
        <SlidingCount
          value={current.memberCount}
          format={countOf}
          className='text-muted-foreground text-xs font-normal'
        />
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-72'>
        <DropdownMenuGroup>
          <DropdownMenuGroupLabel>Teams</DropdownMenuGroupLabel>
          <DropdownMenuRadioGroup value={currentId} onValueChange={switchTeam}>
            {TEAMS.map((team) => (
              <DropdownMenuRadioItem
                key={team.id}
                value={team.id}
                closeOnClick
                className='h-9'
              >
                <TeamRow team={team} />
              </DropdownMenuRadioItem>
            ))}
          </DropdownMenuRadioGroup>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <SettingsIcon />
          Settings of {current.name}
        </DropdownMenuItem>
        <DropdownMenuItem>
          <UsersIcon />
          All teams
        </DropdownMenuItem>
        <DropdownMenuItem>
          <PlusIcon />
          Create team
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

const ARRIVE: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const LEAVE: Transition = { duration: 0.1, ease: [0.2, 0, 0, 1] };

const BLUR_VARIANTS: Variants = {
  enter: { opacity: 0, filter: 'blur(2px)' },
  visible: { opacity: 1, filter: 'blur(0px)', transition: ARRIVE },
  exit: { opacity: 0, filter: 'blur(2px)', transition: LEAVE },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1, transition: ARRIVE },
  exit: { opacity: 0, transition: LEAVE },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return BLUR_VARIANTS;
}

type MorphLabelProps = {
  /** Changes when the label becomes another one. */
  value: string;
  className?: string;
  children: React.ReactNode;
};

/** A label that becomes another: the text crossfades through a light blur while its width follows. */
export function MorphLabel({ value, className, children }: MorphLabelProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={value}
          variants={variantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          className={cn('flex whitespace-nowrap', className)}
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </AnimatedSize>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

const SHIFT_PX = 8;

const SLIDE_TRANSITION: Transition = { duration: 0.18, ease: [0.2, 0, 0, 1] };

const SLIDE_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: offset };
  },
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => {
    const offset = direction * SHIFT_PX;
    return { opacity: 0, y: -offset };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SLIDE_VARIANTS;
}

function directionOf(previous: number, next: number) {
  if (next > previous) {
    return 1;
  }
  return -1;
}

type Shown = { value: number; direction: number };

type SlidingCountProps = {
  value: number;
  /** Writes the figure in words, with its singular branch. */
  format: (value: number) => string;
  className?: string;
};

/** A figure the person just changed: it slides in the direction of the change. */
export function SlidingCount({ value, format, className }: SlidingCountProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [shown, setShown] = useState<Shown>({ value, direction: 1 });
  const text = format(value);

  if (shown.value !== value) {
    const direction = directionOf(shown.value, value);
    setShown({ value, direction });
  }

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence
        mode='popLayout'
        initial={false}
        custom={shown.direction}
      >
        <motion.span
          key={text}
          custom={shown.direction}
          variants={variantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SLIDE_TRANSITION}
          className='whitespace-nowrap'
        >
          {text}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { cn } from '@/registry/ndeko/lib/utils';

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: [0.2, 0, 0, 1] };

const SWAP_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function variantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  /** Changes when the content becomes another one. */
  swapKey: string;
  className?: string;
  children: React.ReactNode;
};

/** An icon that becomes another: the old one shrinks out of focus while the new one settles. */
export function Swap({ swapKey, className, children }: SwapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <AnimatePresence mode='popLayout' initial={false}>
      <motion.span
        key={swapKey}
        variants={variantsOf(shouldReduceMotion)}
        initial='enter'
        animate='visible'
        exit='exit'
        transition={SWAP_TRANSITION}
        className={cn('flex', className)}
      >
        {children}
      </motion.span>
    </AnimatePresence>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

const SIZE_CLASS = {
  sm: 'size-5 rounded-[5px]',
  md: 'size-6 rounded-md',
  lg: 'size-9 rounded-lg',
} as const;

type TeamTileProps = {
  name: string;
  color: string;
  size?: keyof typeof SIZE_CLASS;
  className?: string;
};

/** A team without a logo: a picture drawn from its name, in its colour. */
export function TeamTile({
  name,
  color,
  size = 'md',
  className,
}: TeamTileProps) {
  const sizeClass = SIZE_CLASS[size];

  return (
    <MeshTile seed={name} color={color} className={cn(sizeClass, className)} />
  );
}

export type Team = {
  id: string;
  name: string;
  /** The colour the team picked for its tile. */
  color: string;
  memberIds: string[];
  memberCount: number;
};

export const TEAMS: Team[] = [
  {
    id: 'atlas',
    name: 'Atlas Redesign',
    color: 'var(--info)',
    memberIds: ['amara', 'leo', 'sana', 'tomas', 'mei', 'jonas'],
    memberCount: 6,
  },
  {
    id: 'field',
    name: 'Field App',
    color: 'var(--success)',
    memberIds: ['leo', 'sana', 'jonas'],
    memberCount: 5,
  },
  {
    id: 'growth',
    name: 'Growth',
    color: 'var(--warning)',
    memberIds: ['mei', 'amara'],
    memberCount: 4,
  },
  {
    id: 'platform',
    name: 'Platform',
    color: 'var(--primary)',
    memberIds: ['sana', 'tomas', 'jonas'],
    memberCount: 7,
  },
  {
    id: 'research',
    name: 'Research',
    color: 'var(--muted-foreground)',
    memberIds: ['mei'],
    memberCount: 1,
  },
];

export function memberCountLabelOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}
